--
-- Table structure for table `quotations`
--

DROP TABLE IF EXISTS `quotations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quotations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `revision` smallint unsigned DEFAULT NULL,
  `sequence_year` smallint unsigned DEFAULT NULL,
  `sequence_month` tinyint unsigned DEFAULT NULL,
  `sequence_number` int unsigned DEFAULT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `client_id` bigint unsigned NOT NULL,
  `quote_date` date NOT NULL,
  `valid_until` date DEFAULT NULL,
  `reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `salesperson` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sales_admin` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_terms` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_availability` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_details` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `invoice_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoice_date` date DEFAULT NULL,
  `invoice_sequence_year` smallint unsigned DEFAULT NULL,
  `invoice_sequence_month` tinyint unsigned DEFAULT NULL,
  `invoice_sequence_number` int unsigned DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT '0.00',
  `discount_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `vat_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `additional_discount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `grand_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `terms` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quotations_number_unique` (`number`),
  UNIQUE KEY `quotations_invoice_number_unique` (`invoice_number`),
  KEY `quotations_parent_id_foreign` (`parent_id`),
  KEY `quotations_client_id_foreign` (`client_id`),
  KEY `quotations_created_by_foreign` (`created_by`),
  KEY `quotations_sequence_year_sequence_month_sequence_number_index` (`sequence_year`,`sequence_month`,`sequence_number`),
  KEY `quotations_base_number_index` (`base_number`),
  KEY `quotations_status_index` (`status`),
  KEY `quotations_invoice_sequence_index` (`invoice_sequence_year`,`invoice_sequence_month`,`invoice_sequence_number`),
  CONSTRAINT `quotations_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `quotations_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotations_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `quotations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `quotations`
--

LOCK TABLES `quotations` WRITE;
