DROP TABLE IF EXISTS `receipt_vouchers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `receipt_vouchers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `proforma_invoice_id` bigint unsigned NOT NULL,
  `number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `received_date` date NOT NULL,
  `sequence_year` smallint unsigned NOT NULL,
  `sequence_month` tinyint unsigned NOT NULL,
  `sequence_number` int unsigned NOT NULL,
  `payment_mode` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(14,2) NOT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `receipt_vouchers_proforma_invoice_id_unique` (`proforma_invoice_id`),
  UNIQUE KEY `receipt_vouchers_number_unique` (`number`),
  KEY `receipt_vouchers_created_by_foreign` (`created_by`),
  KEY `receipt_vouchers_sequence_index` (`sequence_year`,`sequence_month`,`sequence_number`),
  CONSTRAINT `receipt_vouchers_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `receipt_vouchers_proforma_invoice_id_foreign` FOREIGN KEY (`proforma_invoice_id`) REFERENCES `proforma_invoices` (`id`) ON DELETE CASCADE
